actionConfiguration.body:
insert into public.kalenterimerkinnat (pvm, alkaa, paattyy, otsikko, kuvaus, laji)
values (
  {{(mPvm.selectedDate ? moment(mPvm.selectedDate).format('YYYY-MM-DD') : '')}}::date,
  public.muotoile_kello({{mAlkaa.text}}::text),
  public.muotoile_kello({{mPaattyy.text}}::text),
  btrim({{mOtsikko.text}}::text),
  nullif(btrim({{mKuvaus.text}}::text), ''),
  coalesce(nullif({{mLaji.selectedOptionValue}}::text, ''), 'muu')
)
returning id;
